async ({ workspace: { read, search }, git: { status, log } }) => {
  const [skill, ret, checks, npmrun, wait, st, lg] = await Promise.all([
    read(".pi/skills/pit-delivery/SKILL.md", { format: "raw" }),
    search("Returned ", { path: "src", limit: 20 }),
    search("checks are still pending", { limit: 10 }),
    search("npm run, exit", { limit: 10 }),
    search("requestedAttempts", { limit: 30 }),
    status(["--short", "--branch"]),
    log(["--oneline", "-5"]),
  ]);
  return { skill: skill.content, ret, checks, npmrun, wait, st: st.stdout, lg: lg.stdout };
}
